    internal sealed class SidebarBrand : Label {
        protected override void OnPaint(PaintEventArgs e){TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(Padding.Left,0,Math.Max(0,Width-Padding.Left),Height),ForeColor,TextFormatFlags.Left|TextFormatFlags.Top|TextFormatFlags.NoPadding);}
    }
    internal sealed class SidebarButton : Button {
        public const int TextInset=36;
        internal int IconLeft {get{var brand=Parent==null?null:Parent.Controls["sidebarBrand"];return brand==null?Padding.Left:brand.Left+brand.Padding.Left-Left;}}
        internal int TextLeft {get{return IconLeft+Padding.Left*2;}}
        void DrawNavigationIcon(Graphics graphics){
            float size=Math.Max(12,Padding.Left*7f/6f),x=IconLeft,y=(Height-size)/2f;
            var saved=graphics.Save();graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
            using(var pen=new Pen(ForeColor,Math.Max(1,size/14f))){
                string kind=Convert.ToString(Tag);
                if(kind=="⚙"){
                    var points=new PointF[32];float cx=x+size/2,cy=y+size/2;
                    for(int i=0;i<points.Length;i++){double angle=(i-0.5)*Math.PI/16;float radius=size*(i%4==1||i%4==2?0.5f:0.37f);points[i]=new PointF(cx+(float)Math.Cos(angle)*radius,cy+(float)Math.Sin(angle)*radius);}
                    graphics.DrawPolygon(pen,points);graphics.DrawEllipse(pen,cx-size*0.16f,cy-size*0.16f,size*0.32f,size*0.32f);
                }else if(kind=="◷"){
                    graphics.DrawEllipse(pen,x,y,size,size);graphics.DrawLine(pen,x+size/2,y+size*0.2f,x+size/2,y+size/2);graphics.DrawLine(pen,x+size/2,y+size/2,x+size*0.78f,y+size/2);
                }else if(kind=="≡"){
                    foreach(float line in new[]{0.2f,0.5f,0.8f})graphics.DrawLine(pen,x,y+size*line,x+size,y+size*line);
                }else{
                    graphics.DrawRectangle(pen,x,y,size,size);
                    if(kind=="◫")graphics.DrawLine(pen,x+size*0.35f,y,x+size*0.35f,y+size);
                    else graphics.DrawRectangle(pen,x+size*0.28f,y+size*0.28f,size*0.44f,size*0.44f);
                }
            }
            graphics.Restore(saved);
        }
        protected override void OnPaint(PaintEventArgs e){
            using(var brush=new SolidBrush(BackColor))e.Graphics.FillRectangle(brush,ClientRectangle);
            var flags=TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding;
            DrawNavigationIcon(e.Graphics);
            TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(TextLeft,0,Math.Max(0,Width-TextLeft-4),Height),ForeColor,flags);
            if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(e.Graphics,Rectangle.Inflate(ClientRectangle,-3,-3));
        }
    }
